<?php
require_once __DIR__.'/app/lib/Db.php';require_once __DIR__.'/app/lib/Security.php';Security::start();$u=Security::requireRole(['reviewer','admin','super_admin']);$csrf=Security::csrf();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vendor Self-Service Review | TechSelectAI</title><style>body{font-family:system-ui;background:#f6f8fb;color:#172033;margin:0}.wrap{max-width:1200px;margin:auto;padding:28px}.card{background:#fff;border:1px solid #dfe6ee;border-radius:14px;padding:16px;margin:12px 0}.row{display:grid;grid-template-columns:1fr auto;gap:12px;align-items:start}.meta{color:#667085;font-size:13px}button{padding:9px 12px;border:0;border-radius:8px;background:#123b67;color:#fff;cursor:pointer;margin:4px}.reject{background:#8b1e2d}</style></head><body><div class="wrap"><h1>Vendor Self-Service Review</h1><p>Review company claims and vendor-submitted factual updates. Approval never grants control over TechSelectAI scores, rankings or recommendations.</p><div id="claims"></div><div id="updates"></div></div><script>const csrf=<?php echo json_encode($csrf)?>;async function load(){let r=await fetch('/api/vendor-self-service-admin');let d=await r.json();claims.innerHTML='<h2>Company claims</h2>'+d.claims.map(c=>`<div class="card row"><div><b>${e(c.vendor_name)}</b><div class="meta">${e(c.user_email)} · ${e(c.verification_method)} · ${e(c.company_email||'')} · ${e(c.evidence_url||'')}</div><p>${e(c.evidence_note||'')}</p></div><div><button onclick="claim(${c.id},'verify')">Verify</button><button class="reject" onclick="claim(${c.id},'reject')">Reject</button></div></div>`).join('');updates.innerHTML='<h2>Factual update requests</h2>'+d.updates.map(x=>`<div class="card row"><div><b>${e(x.vendor_name)}${x.product_name?' / '+e(x.product_name):''}</b><div class="meta">${e(x.user_email)} · ${e(x.update_type)} · ${e(x.field_key||'')}</div><p><b>Current:</b> ${e(x.current_value||'—')}<br><b>Proposed:</b> ${e(x.proposed_value||'')}<br><b>Evidence:</b> ${e(x.evidence_url||'—')}</p></div><div><button onclick="upd(${x.id},'approve')">Approve</button><button class="reject" onclick="upd(${x.id},'reject')">Reject</button></div></div>`).join('')}function e(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}async function send(url,b){let r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(b)});if(!r.ok)alert((await r.json()).error||'Failed');load()}function claim(id,a){let reason=a==='reject'?prompt('Rejection reason')||'':'';if(a==='reject'&&!reason)return;send(`/api/vendor-self-service-admin/claims/${id}/${a}`,{reason})}function upd(id,a){let note=prompt(a==='approve'?'Reviewer note (optional)':'Rejection reason')||'';if(a==='reject'&&!note)return;send(`/api/vendor-self-service-admin/updates/${id}/${a}`,{note})}load()</script></body></html>